// Explicit loopback-only start of the candidate generated by validate-candidate.cjs.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process'),crypto=require('node:crypto');
const root=path.resolve(__dirname,'../..'),privateDir=path.join(root,'delivery-private');
const target=fs.readFileSync(path.join(privateDir,'arc33-candidate-location.txt'),'utf8').trim();
if(path.dirname(path.resolve(target))!==privateDir||!path.basename(target).startsWith('arc33-candidate-')||fs.realpathSync(target)!==target)throw Error('Unexpected candidate target');
if(!fs.existsSync(path.join(target,'.next/BUILD_ID')))throw Error('Build the isolated candidate first');
const env={};for(const [k,v] of Object.entries(process.env))if(/^(PATH|SystemRoot|windir|TEMP|TMP|USERPROFILE|LOCALAPPDATA|APPDATA)$/i.test(k))env[k]=v;
Object.assign(env,{NODE_ENV:'production',CI:'true',NEXT_TELEMETRY_DISABLED:'1',NEXT_PUBLIC_APP_URL:'http://127.0.0.1:3006',SESSION_SECRET:crypto.randomBytes(32).toString('hex'),PAYMENT_PROVIDER:'local',GETYOURMENTOR_ALLOW_DEMO:'true',GETYOURMENTOR_ACCEPTANCE_MODE:'true',NODE_OPTIONS:'--require '+JSON.stringify(path.join(target,'network-guard.cjs'))});
const child=cp.spawn(process.execPath,[path.join(target,'node_modules/next/dist/bin/next'),'start','--hostname','127.0.0.1','--port','3006'],{cwd:target,env,stdio:'inherit',windowsHide:true});
fs.writeFileSync(path.join(privateDir,'arc33-server-pid.json'),JSON.stringify({pid:child.pid,target}));
child.on('error',error=>{console.error(error.message);process.exitCode=1;});
child.on('exit',code=>process.exit(code??0));
process.on('SIGINT',()=>child.kill());
process.on('SIGTERM',()=>child.kill());
